const DEFAULTS = Object.freeze({
  enabled: true, maxWidth: 280,
  displayMode: 'translation', fontSize: 13, fontWeight: 'medium',
  colorMode: 'system', originalColor: '#FFFFFF', translationColor: '#CDE8FF', opacity: 1,
  progressiveHighlight: true, unplayedOpacity: .35,
  longLine: 'ellipsis', scrollSpeed: 28, scrollDelay: 1.5, offsetMs: 0,
  idleBehavior: 'title', pauseBehavior: 'keep', pauseDelay: 10,
  filterCredits: true, customFilters: [],
});

// Keep the visible color stable during the host's asynchronous cover extraction.
// A known color for the same artwork stays valid; a previous song's color is only a short bridge.
class CoverColorState {
  constructor(waitMs = 2000) { this.waitMs = waitMs; this.colors = new Map(); this.key = ''; this.since = null; this.lastColor = null; }
  resolve({ trackId, coverUrl, color, ready }, now = Date.now()) {
    const key = trackId ? String(coverUrl || trackId) : '';
    if (!key) { this.key = ''; this.since = null; return { color: null, pending: false, expiresAt: 0 }; }
    if (key !== this.key) { this.key = key; this.since = now; }
    if (ready && /^#[\da-f]{6}$/i.test(color || '')) {
      this.lastColor = color; this.since = null;
      this.colors.delete(key); this.colors.set(key, color);
      if (this.colors.size > 32) this.colors.delete(this.colors.keys().next().value);
      return { color, pending: false, expiresAt: 0 };
    }
    const cached = this.colors.get(key);
    if (cached) { this.lastColor = cached; return { color: cached, pending: false, expiresAt: 0 }; }
    this.since ??= now;
    const expiresAt = this.since + this.waitMs;
    if (now < expiresAt) return { color: this.lastColor, pending: true, expiresAt };
    return { color: null, pending: false, expiresAt: 0 };
  }
}

function sanitizeConfig(input = {}) {
  if (!input || typeof input !== 'object') input = {};
  const out = { ...DEFAULTS };
  for (const key of ['enabled', 'filterCredits', 'progressiveHighlight'])
    if (typeof input[key] === 'boolean') out[key] = input[key];
  const enums = {
    colorMode: ['system', 'cover', 'custom'],
    displayMode: ['original', 'translation', 'bilingual', 'bilingualInline'], fontWeight: ['regular', 'medium', 'semibold', 'bold'],
    longLine: ['ellipsis', 'scroll'], idleBehavior: ['title', 'hold', 'hide'], pauseBehavior: ['keep', 'dim', 'hide'],
  };
  for (const [key, values] of Object.entries(enums)) if (values.includes(input[key])) out[key] = input[key];
  const limits = { maxWidth: [128, 800], fontSize: [9, 24], opacity: [.2, 1], scrollSpeed: [8, 100],
    scrollDelay: [0, 8], offsetMs: [-30000, 30000], pauseDelay: [0, 300], unplayedOpacity: [.1, .8] };
  for (const [key, [min, max]] of Object.entries(limits))
    if (typeof input[key] === 'number' && Number.isFinite(input[key])) out[key] = Math.min(max, Math.max(min, input[key]));
  for (const key of ['originalColor', 'translationColor'])
    if (/^#[\da-f]{6}$/i.test(input[key] || '')) out[key] = input[key];
  if (Array.isArray(input.customFilters)) out.customFilters = input.customFilters.filter(x => typeof x === 'string' && x.trim()).slice(0, 40).map(x => x.trim().slice(0, 500));
  return out;
}

function parseFilter(pattern) {
  const text = pattern.trim();
  if (text.length > 500) throw new Error('单条正则最长 500 字符');
  const match = text.match(/^\/(.*)\/([a-z]*)$/i);
  if (match && /[^imu]/.test(match[2])) throw new Error('正则标志仅支持 i、m、u');
  return new RegExp(match ? match[1] : text, match ? match[2] : 'iu');
}

function validateFilters(patterns) {
  if (patterns.length > 40) return ['最多支持 40 条正则规则'];
  return patterns.map((pattern, index) => {
    try { parseFilter(pattern); return null; }
    catch (error) { return `第 ${index + 1} 条：${error.message}`; }
  }).filter(Boolean);
}

// Kept independent so the exact same evaluator can run inside a disposable Worker.
function evaluateFilters(lines, config) {
  const credit = /^\s*(?:[（(【\[]\s*)?(?:作词|作曲|词曲|编曲|制作人|制作|出品人|出品|监制|录音(?:师)?|混音(?:师)?|母带(?:工程师)?|吉他(?:手)?|贝斯(?:手)?|键盘(?:手)?|鼓手|和声(?:编写)?|弦乐|配唱制作人|音乐总监|录音棚|词|曲|Lyrics(?:\s+by)?|Compos(?:er|ed\s+by)|Arrang(?:er|ed\s+by)|Producer|Guitar|Bass|Drums|Mix(?:ing)?|Master(?:ing)?|Recorded\s+by)\s*[:：]/iu;
  const rules = config.customFilters.map(pattern => {
    const match = pattern.match(/^\/(.*)\/([imu]*)$/);
    return new RegExp(match ? match[1] : pattern, match ? match[2] : 'iu');
  });
  return lines.map(line => {
    const values = [line.original, line.translation];
    return (config.filterCredits && values.some(x => credit.test(x))) || rules.some(rule => values.some(x => rule.test(x)));
  });
}

function normalizeLines(snapshot) {
  const playback = snapshot?.playback;
  const lyric = snapshot?.lyric;
  if (!playback || !lyric || !Array.isArray(lyric.lines)) return [];
  const ids = [playback.trackId, playback.lyricHash].filter(Boolean).map(String);
  if (lyric.trackId != null && !ids.includes(String(lyric.trackId))) return [];
  return lyric.lines.slice(0, 20000).map((line, order) => {
    const characterTime = line.characters?.[0]?.startTime;
    const startMs = Number.isFinite(characterTime) ? characterTime : Number(line.time || 0) * 1000;
    const original = String(line.text ?? '').trim(), translation = String(line.translated ?? '').trim();
    return { startMs: Math.max(0, startMs), original, translation, order,
      originalTiming: normalizeCharacterTiming(original, line.characters),
      translationTiming: normalizeCharacterTiming(translation, line.translatedCharacters) };
  }).filter(line => Number.isFinite(line.startMs)).sort((a, b) => a.startMs - b.startMs || a.order - b.order);
}

function normalizeCharacterTiming(text, characters) {
  if (!Array.isArray(characters)) return [];
  let cursor = 0;
  const result = [];
  for (const character of characters) {
    const value = String(character.text ?? '');
    const startMs = Number(character.startTime), endMs = Number(character.endTime);
    if (!value.trim()) continue;
    const index = text.indexOf(value.trim(), cursor);
    if (index < 0 || !Number.isFinite(startMs) || !Number.isFinite(endMs) || endMs <= startMs) continue;
    const end = index + value.trim().length;
    result.push({ start: index, end, startMs, endMs }); cursor = end;
  }
  return result;
}

const CLOCK_LIMIT_MS = 1800;

function playbackWithLiveClock(playback, clock) {
  if (!playback || !clock || String(clock.trackId) !== String(playback.trackId) ||
      !Number.isFinite(clock.positionMs) || !Number.isFinite(clock.sampledAt) || clock.sampledAt <= 0 ||
      clock.sampledAt < (playback.clock?.sampledAt ?? playback.updatedAt ?? 0)) return playback;
  return { ...playback, isPlaying: clock.isPlaying ?? playback.isPlaying, clock };
}

function samplePlayback(playback, now) {
  const clock = playback.clock;
  const position = Number(clock?.positionMs ?? Number(playback.currentTime || 0) * 1000);
  const rate = Math.max(.1, Number(clock?.playbackRate ?? playback.playbackRate ?? 1) || 1);
  const advancing = !!(clock?.isPlaying ?? playback.isPlaying) && (clock?.isAdvancing ?? true);
  const duration = Number(clock?.durationMs ?? Number(playback.duration || 0) * 1000);
  const age = Math.max(0, now - Number(clock?.sampledAt ?? playback.updatedAt ?? now));
  // Freeze stale samples instead of running ahead indefinitely after sleep/disconnect.
  const time = Math.max(0, position + (advancing ? Math.min(CLOCK_LIMIT_MS, age) * rate : 0));
  return { time: duration > 0 ? Math.min(time, duration) : time, rate, advancing, duration,
    advanceLimitMs: Math.max(0, CLOCK_LIMIT_MS - age) };
}

const lyricOffset = (snapshot, config) => Number(snapshot.lyric?.timeOffset || 0) + config.offsetMs;

function lineTiming(snapshot, lines, index, config, now, timelineMs, sample) {
  const line = lines[index], p = snapshot.playback;
  const next = lines[index + 1];
  const lastCharacterEnd = Math.max(0, ...line.originalTiming.map(x => x.endMs));
  const endMs = lastCharacterEnd > line.startMs ? lastCharacterEnd : next?.startMs ?? Math.max(line.startMs + 1000, Number(p.duration || 0) * 1000);
  const originalFirst = config.displayMode !== 'translation' || !line.translation;
  const inlineBilingual = config.displayMode === 'bilingualInline' && !!line.translation;
  const doubleBilingual = config.displayMode === 'bilingual' && !!line.translation;
  return {
    timelineMs, sampledAt: now, startMs: line.startMs, endMs,
    advancing: sample.advancing, rate: sample.rate, advanceLimitMs: sample.advanceLimitMs,
    primary: inlineBilingual ? [] : originalFirst ? line.originalTiming : line.translationTiming,
    secondary: doubleBilingual ? line.translationTiming : [],
  };
}

function estimatedPlaybackMs(playback, now = Date.now()) {
  return playback ? samplePlayback(playback, now).time : 0;
}

function findLineIndex(lines, timeMs) {
  let low = 0, high = lines.length - 1, result = -1;
  while (low <= high) {
    const mid = (low + high) >> 1;
    if (lines[mid].startMs <= timeMs) { result = mid; low = mid + 1; } else high = mid - 1;
  }
  return result;
}

function nextDisplayDelay(snapshot, lines, config, now, pausedAt, filterPending) {
  const playback = snapshot.playback;
  if (!playback) return null;
  if (!playback.isPlaying && pausedAt != null && config.pauseBehavior !== 'keep') {
    const delay = pausedAt + config.pauseDelay * 1000 - now;
    return delay > 0 ? delay : null;
  }
  if (filterPending || !lines.length) return null;
  const sample = samplePlayback(playback, now);
  if (!sample.advancing) return null;
  const offset = lyricOffset(snapshot, config);
  const timeline = sample.time + offset;
  const next = lines[findLineIndex(lines, timeline) + 1];
  if (!next || (sample.duration > 0 && next.startMs - offset > sample.duration)) return null;
  const delay = (next.startMs - timeline) / sample.rate;
  return delay > 0 && delay <= sample.advanceLimitMs ? delay : null;
}

function displayState(snapshot, lines, hidden, config, now = Date.now(), lastVisible = null, pausedAt = null, filterPending = false) {
  const p = snapshot?.playback;
  const trackId = String(p?.trackId ?? '');
  const base = { trackId, title: String(p?.title ?? ''), artist: String(p?.artist ?? ''),
    hasTrack: !!p?.trackId, isPlaying: !!p?.isPlaying, isFavorite: !!p?.isFavorite,
    playMode: ['sequential', 'list', 'random', 'single'].includes(p?.playMode) ? p.playMode : 'list', appearanceDark: !!snapshot?.appearance?.isDark,
    coverColor: /^#[\da-f]{6}$/i.test(snapshot?.appearance?.coverColor || '') ? snapshot.appearance.coverColor : null,
    coverColorPending: !!snapshot?.appearance?.coverColorPending, filterPending: !!filterPending,
    primary: '', secondary: '', original: '', translation: '', reason: 'empty', hidden: false, dimmed: false };
  if (!p) return { ...base, primary: 'EchoMusic', reason: 'empty' };
  const sample = samplePlayback(p, now), timeline = sample.time + lyricOffset(snapshot, config);
  const index = findLineIndex(lines, timeline);
  const line = index >= 0 ? lines[index] : null;
  if (filterPending) {
    base.reason = 'filtering';
    if (config.idleBehavior === 'hide') base.hidden = true;
    else base.primary = [base.title, base.artist].filter(Boolean).join(' · ');
  } else if (line && !hidden[index] && line.original) {
    base.original = line.original; base.translation = line.translation; base.reason = 'lyric';
    if (config.displayMode === 'translation') base.primary = line.translation || line.original;
    else if (config.displayMode === 'bilingual') { base.primary = line.original; base.secondary = line.translation; }
    else if (config.displayMode === 'bilingualInline') base.primary = [line.original, line.translation].filter(Boolean).join('  ·  ');
    else base.primary = line.original;
    base.timing = lineTiming(snapshot, lines, index, config, now, timeline, sample);
  } else {
    base.reason = snapshot.lyric?.isLoading ? 'loading' : hidden[index] ? 'filtered' : lines.length ? 'interlude' : 'noLyrics';
    if (config.idleBehavior === 'hold' && lastVisible?.trackId === trackId) {
      base.primary = lastVisible.primary; base.secondary = lastVisible.secondary;
      base.original = lastVisible.original; base.translation = lastVisible.translation;
    } else if (config.idleBehavior === 'hide') base.hidden = true;
    else base.primary = [base.title, base.artist].filter(Boolean).join(' · ');
  }
  if (!p.isPlaying && pausedAt != null && now - pausedAt >= config.pauseDelay * 1000) {
    if (config.pauseBehavior === 'hide') base.hidden = true;
    if (config.pauseBehavior === 'dim') base.dimmed = true;
  }
  if (config.colorMode === 'cover' && base.coverColorPending && !base.coverColor) base.hidden = true;
  return base;
}


class FilterRunner {
  constructor() { this.pending = null; this.destroyed = false; }
  cancel() { this.pending?.cancel(); this.pending = null; }
  async run(lines, config) {
    this.cancel();
    if (this.destroyed) throw new Error('过滤器已关闭');
    if (!config.filterCredits && !config.customFilters.length) return lines.map(() => false);
    const source = `const evaluate = ${evaluateFilters.toString()}; onmessage = e => { try { postMessage({ result: evaluate(e.data.lines, e.data.config) }); } catch(error) { postMessage({ error: error.message }); } };`;
    const url = URL.createObjectURL(new Blob([source], { type: 'text/javascript' }));
    let worker;
    try { worker = new Worker(url); } finally { URL.revokeObjectURL(url); }
    return new Promise((resolve, reject) => {
      let settled = false;
      const done = (error, result) => {
        if (settled) return; settled = true; clearTimeout(timer); worker.terminate();
        if (this.pending === task) this.pending = null;
        if (error) reject(error); else resolve(result);
      };
      const task = { cancel: () => done(new DOMException('过滤任务已替换', 'AbortError')) };
      const timer = setTimeout(() => done(new Error('过滤执行超时，请简化正则；本次自定义过滤未应用')), 350);
      this.pending = task;
      worker.onmessage = event => event.data.error ? done(new Error(event.data.error)) : done(null, event.data.result);
      worker.onerror = event => done(new Error(event.message || '过滤器启动失败'));
      worker.postMessage({ lines, config });
    });
  }
  dispose() { this.destroyed = true; this.cancel(); }
}

function registerSettings(ctx, session) {
  const { h, ref, onMounted, onUnmounted } = ctx.vue;
  ctx.ui.settings.define({ title: 'Mac 菜单栏歌词', component: {
    setup() {
      const url = ref(session.settingsURL), status = ref(session.status);
      let unsubscribe;
      onMounted(() => { unsubscribe = session.subscribe(() => { url.value = session.settingsURL; status.value = session.status; }); });
      onUnmounted(() => unsubscribe?.());
      return () => url.value
        ? h('iframe', { src: url.value, title: '菜单栏歌词设置', sandbox: 'allow-scripts allow-same-origin',
          style: 'display:block;width:100%;height:76vh;min-height:520px;border:0;border-radius:12px;background:transparent' })
        : h('div', { style: 'padding:24px' }, [h('p', status.value), h('button', { onClick: () => session.launch() }, '启动菜单栏组件')]);
    },
  } });
}


function createSession(ctx) {
  let config = sanitizeConfig(), snapshot = {}, lines = [], hidden = [], signature = '';
  let lastVisible = null, pausedAt = null, lastPlaying = null, disposed = false, helperPid = 0;
  let server = null, filterGeneration = 0, filterPending = false, currentState = null, status = '正在初始化…', launching = false;
  let launchGeneration = 0, configureQueue = Promise.resolve();
  let displayTimer = null;
  const playerStore = ctx.player?.store;
  const coverColors = new CoverColorState();
  let coverTimer = null, coverExpiresAt = 0;
  const clients = new Set(), nativeClients = new Set(), listeners = new Set(), timers = [], actionTimers = new Set(), cleanups = [];
  const filter = new FilterRunner(), previewFilter = new FilterRunner();
  const secret = Array.from(crypto.getRandomValues(new Uint8Array(24)), x => x.toString(16).padStart(2, '0')).join('');
  const protocol = 'echo-lyrics.' + secret;
  const notify = () => listeners.forEach(fn => fn());
  const setStatus = text => { status = text; notify(); };
  const send = (socket, message) => Promise.resolve(socket.send(JSON.stringify(message))).catch(() => { clients.delete(socket); });
  const broadcast = message => { if (!disposed) clients.forEach(socket => void send(socket, message)); };
  const emit = () => {
    if (disposed) return;
    const playMode = ctx.player?.playMode?.value ?? snapshot.playback?.playMode;
    const theme = ctx.stores?.theme;
    const now = Date.now();
    const playback = playbackWithLiveClock(snapshot.playback, playerStore?.playbackClock);
    if (playback?.isPlaying !== lastPlaying) {
      pausedAt = playback?.isPlaying === false ? now : null;
      lastPlaying = playback?.isPlaying;
    }
    const cover = coverColors.resolve({ trackId: snapshot.playback?.trackId, coverUrl: snapshot.playback?.coverUrl,
      color: theme?.coverColor ?? snapshot.appearance?.coverColor, ready: theme ? theme.coverColorReady : !!snapshot.appearance?.coverColor }, now);
    if (cover.expiresAt !== coverExpiresAt) {
      clearTimeout(coverTimer); coverExpiresAt = cover.expiresAt;
      coverTimer = cover.expiresAt ? setTimeout(emit, Math.max(1, cover.expiresAt - now)) : null;
    }
    const displaySnapshot = { ...snapshot, appearance: { ...snapshot.appearance, coverColor: cover.color, coverColorPending: cover.pending }, playback: playback ? { ...playback, playMode } : null };
    const state = displayState(displaySnapshot, lines, hidden, config, now, lastVisible, pausedAt, filterPending);
    if (state.reason === 'lyric') lastVisible = state;
    const text = JSON.stringify(state);
    if (text !== currentState) { currentState = text; broadcast({ type: 'state', state }); notify(); }
    // Wake at the next lyric boundary, and replace the timer whenever the clock or settings change.
    clearTimeout(displayTimer);
    const delay = nextDisplayDelay(displaySnapshot, lines, config, now, pausedAt, filterPending);
    displayTimer = delay == null ? null : setTimeout(emit, Math.max(1, Math.ceil(delay - (Date.now() - now))));
  };
  const refilter = async () => {
    const generation = ++filterGeneration;
    filterPending = true;
    hidden = lines.map(() => false);
    try {
      const results = await filter.run(lines, config);
      if (!disposed && generation === filterGeneration) { hidden = results; filterPending = false; emit(); }
    } catch (error) {
      if (error.name === 'AbortError' || disposed || generation !== filterGeneration) return;
      // Safe built-in rules remain usable if a custom expression exceeds its budget.
      let fallback;
      try { fallback = await filter.run(lines, { ...config, customFilters: [] }); } catch { fallback = lines.map(() => false); }
      if (disposed || generation !== filterGeneration) return;
      hidden = fallback; filterPending = false; setStatus(error.message); emit();
    }
  };
  const receiveSnapshot = value => {
    if (disposed || !value) return;
    const previousTrack = snapshot.playback?.trackId;
    const previousLyric = snapshot.lyric;
    snapshot = { ...snapshot, ...value };
    if (value.lyric) {
      const changedTrack = String(value.lyric.trackId) !== String(previousLyric?.trackId);
      snapshot.lyric = { ...(changedTrack ? {} : previousLyric), ...value.lyric };
    }
    const p = snapshot.playback;
    if (p?.trackId !== previousTrack) { lastVisible = null; pausedAt = null; lastPlaying = null; }
    const l = snapshot.lyric;
    const nextSignature = [p?.trackId, l?.trackId, l?.revision ?? JSON.stringify(l?.lines ?? [])].join('|');
    if (signature !== nextSignature) { signature = nextSignature; lines = normalizeLines(snapshot); void refilter(); }
    emit();
  };
  const configure = patch => {
    const operation = configureQueue.catch(() => {}).then(async () => {
      if (disposed) throw new Error('插件已停用');
      if (patch.customFilters) {
        const errors = validateFilters(patch.customFilters);
        if (errors.length) throw new Error(errors.join('\n'));
      }
      const next = sanitizeConfig({ ...config, ...patch });
      const errors = validateFilters(next.customFilters);
      if (errors.length) throw new Error(errors.join('\n'));
      await ctx.storage.set('settings', next);
      const filtersChanged = JSON.stringify([config.filterCredits, config.customFilters]) !== JSON.stringify([next.filterCredits, next.customFilters]);
      config = next;
      broadcast({ type: 'config', config }); notify();
      if (filtersChanged) await refilter();
      emit(); return config;
    });
    configureQueue = operation; return operation;
  };
  const launch = async (showSettings = false) => {
    if (launching || disposed || !server) return;
    launching = true; const generation = ++launchGeneration;
    try {
      if (helperPid) { await ctx.process.terminate(helperPid); helperPid = 0; }
      setStatus('等待启动菜单栏组件；首次启动会出现 EchoMusic 原生程序授权提示。');
      const result = await ctx.process.launch({
        executable: 'bin/EchoMenuLyrics.app/Contents/MacOS/EchoMenuLyrics',
        args: showSettings ? ['--settings'] : [], env: { ECHO_LYRICS_ENDPOINT: server.origin.replace(/^http/, 'ws') + '/live', ECHO_LYRICS_PROTOCOL: protocol },
      });
      if (disposed || generation !== launchGeneration) { if (result.ok) await ctx.process.terminate(result.pid); return; }
      if (result.ok) { helperPid = result.pid; setStatus(nativeClients.size ? '菜单栏组件已连接' : '组件已启动，正在连接…'); }
      else setStatus(result.canceled ? '启动授权已取消，可点击启动按钮重试。' : result.error || '菜单栏组件启动失败');
    } catch (error) { setStatus(error.message); } finally { launching = false; }
  };
  const handleMessage = async (socket, raw) => {
    if (typeof raw !== 'string' || raw.length > 65536 || disposed) return;
    let message; try { message = JSON.parse(raw); } catch { return; }
    try {
      if (message.type === 'hello') {
        if (message.role === 'native') { nativeClients.add(socket); setStatus('菜单栏组件已连接'); }
      } else if (message.type === 'nativeAction') {
        if (!['showSettings', 'restart'].includes(message.action)) throw new Error('未知界面操作');
        if (message.action === 'restart') await launch();
        else if (!nativeClients.size) await launch(true);
        else nativeClients.forEach(client => void send(client, { type: 'nativeAction', action: message.action }));
      } else if (message.type === 'preview') {
        const result = await session.preview((message.patterns || []).join('\n'));
        await send(socket, { type: 'preview', lines: result, id: message.id });
      } else if (message.type === 'reset') {
        await configure({ ...DEFAULTS }); await send(socket, { type: 'ack', id: message.id, ok: true });
      } else if (message.type === 'configure') {
        await configure(message.patch); await send(socket, { type: 'ack', id: message.id, ok: true });
      } else if (message.type === 'command') {
        if (!['togglePlayMode', 'togglePlayback', 'previousTrack', 'nextTrack', 'toggleFavorite'].includes(message.command)) throw new Error('未知播放命令');
        if (!snapshot.playback?.trackId || String(message.trackId) !== String(snapshot.playback.trackId)) throw new Error('歌曲已经切换，请重试');
        const accepted = await ctx.nowPlaying.command(message.command);
        if (accepted === false) throw new Error('播放器未接受操作，请重试');
        // This acknowledges dispatch, not a successful favorite mutation; state comes from the host snapshot.
        await send(socket, { type: 'ack', id: message.id, ok: true, dispatched: true });
        const timer = setTimeout(async () => {
          actionTimers.delete(timer);
          try { if (!disposed) receiveSnapshot(await ctx.nowPlaying.getSnapshot()); } catch {}
        }, 200);
        actionTimers.add(timer);
      }
    } catch (error) { await send(socket, { type: 'ack', id: message.id, ok: false, error: error.message }); }
  };
  const session = {
    get config() { return config; }, get status() { return status; }, get state() { return currentState ? JSON.parse(currentState) : null; }, configure, launch,
    get settingsURL() { return server?.ok ? server.origin + '/settings/#' + protocol : null; },
    openSettings() { if (!nativeClients.size) return launch(true); nativeClients.forEach(client => void send(client, { type: 'nativeAction', action: 'showSettings' })); },
    subscribe(fn) { listeners.add(fn); return () => listeners.delete(fn); },
    async preview(text) {
      const patterns = text.split('\n').map(x => x.trim()).filter(Boolean);
      const errors = validateFilters(patterns); if (errors.length) throw new Error(errors.join('\n'));
      const sample = lines.slice();
      const result = await previewFilter.run(sample, sanitizeConfig({ ...config, customFilters: patterns }));
      return sample.map((line, i) => ({ ...line, hidden: result[i] }));
    },
    async start() {
      if (ctx.electron.platform !== 'darwin') { setStatus('本插件仅支持 macOS。'); return; }
      if (!ctx.webServer?.onConnection || !ctx.process?.launch || !ctx.nowPlaying?.getSnapshot) throw new Error('当前 EchoMusic 缺少必要接口，请升级至 2.3.2 或更新版本。');
      config = sanitizeConfig(await ctx.storage.get('settings')); notify();
      const errors = validateFilters(config.customFilters);
      if (errors.length) { config.customFilters = []; setStatus('旧过滤规则无效，已临时停用自定义过滤。'); }
      server = await ctx.webServer.listen({
        path: '/live', onRequest: request => request.path === '/settings/' || request.path === '/settings'
          ? { headers: { 'content-type': 'text/html; charset=utf-8', 'cache-control': 'no-store', 'referrer-policy': 'no-referrer' },
            body: typeof SETTINGS_PAGE_HTML === 'string' ? SETTINGS_PAGE_HTML : '<!doctype html><title>Build required</title>' }
          : { status: 404, body: 'Not found' },
        onUpgrade: request => request.protocols?.includes(protocol) ? { accept: true, protocol } : false,
        onConnection(socket) {
          if (disposed) { socket.close(); return; }
          clients.add(socket);
          void send(socket, { type: 'config', config });
          if (currentState) void send(socket, { type: 'state', state: JSON.parse(currentState) });
          socket.onMessage(event => { void handleMessage(socket, event.data); });
          socket.onClose(() => { clients.delete(socket); nativeClients.delete(socket); if (!disposed && !nativeClients.size) setStatus('菜单栏组件已断开，可从设置中重新启动。'); });
          return () => { clients.delete(socket); nativeClients.delete(socket); };
        },
      });
      if (!server.ok) throw new Error(server.error || '本机歌词服务启动失败');
      notify();
      cleanups.push(ctx.nowPlaying.onSnapshot(receiveSnapshot));
      if (playerStore && 'playbackClock' in playerStore && ctx.vue?.watch) cleanups.push(ctx.vue.watch(() => playerStore.playbackClock, emit));
      if (ctx.player?.playMode && ctx.vue?.watch) cleanups.push(ctx.vue.watch(ctx.player.playMode, emit));
      if (ctx.stores?.theme && ctx.vue?.watch) cleanups.push(ctx.vue.watch(() => [ctx.stores.theme.coverColor, ctx.stores.theme.coverColorReady], emit));
      receiveSnapshot(await ctx.nowPlaying.getSnapshot());
      timers.push(setInterval(() => broadcast({ type: 'heartbeat' }), 3000));
      timers.push(setInterval(async () => { try { if (!disposed) receiveSnapshot(await ctx.nowPlaying.getSnapshot()); } catch {} }, 3000));
      await launch();
    },
    async dispose() {
      if (disposed) return; disposed = true; ++launchGeneration; ++filterGeneration;
      clearTimeout(displayTimer);
      clearTimeout(coverTimer);
      timers.forEach(clearInterval); actionTimers.forEach(clearTimeout); actionTimers.clear(); cleanups.forEach(fn => fn?.());
      filter.dispose(); previewFilter.dispose(); listeners.clear();
      for (const socket of clients) { try { await socket.close(); } catch {} } clients.clear(); nativeClients.clear();
      if (helperPid) { try { await ctx.process.terminate(helperPid); } catch {} helperPid = 0; }
      try { await ctx.webServer.close(); } catch {}
    },
  };
  return session;
}

let activeSession;
async function activate(ctx) {
  const session = createSession(ctx); activeSession = session;
  registerSettings(ctx, session);
  ctx.dispose(() => session.dispose());
  try { await session.start(); } catch (error) { ctx.toast.warning(`菜单栏歌词：${error.message}`); await session.dispose(); }
}
async function deactivate() { const session = activeSession; activeSession = null; await session?.dispose(); }

export { activate, deactivate };
